import itertools

# Generate points of PG(3,2) - non-zero vectors in GF(2)^4
points = []
for i in range(1, 16):
    # Represent as binary tuple
    vec = tuple((i >> (3-j)) & 1 for j in range(4))
    points.append(vec)

# Map points to indices 0..14
point_to_idx = {p: i for i, p in enumerate(points)}

# Generate all lines (blocks) of STS(15)
# For each pair of distinct points, the line is {a, b, a+b}
blocks_set = set()
for i in range(15):
    for j in range(i+1, 15):
        a = points[i]
        b = points[j]
        c = tuple((a[k] ^ b[k]) for k in range(4))
        if c == (0,0,0,0):
            continue
        # Sort indices
        block = tuple(sorted([point_to_idx[a], point_to_idx[b], point_to_idx[c]]))
        blocks_set.add(block)

blocks = sorted(blocks_set)
print(f"Number of blocks: {len(blocks)}")
for b in blocks:
    print(b)

# Verify STS properties
# Each pair appears exactly once
pair_count = {}
for b in blocks:
    for i in range(3):
        for j in range(i+1, 3):
            pair = (b[i], b[j])
            pair_count[pair] = pair_count.get(pair, 0) + 1

print(f"Max pair count: {max(pair_count.values())}, min: {min(pair_count.values())}")
print(f"Number of pairs: {len(pair_count)}")
